export const EXTENDED_OFFLINE_LEXICON: Record<string, OfflineEntry> = (() => {
  const out: Record<string, OfflineEntry> = {};
  for (const [k, raw] of Object.entries(RAW_LEXICON)) {
    const cleanKey = k.replace(/_v$/, "");
    const [pos, def, synsStr] = raw.split("|");
    const syns = synsStr
      ? synsStr
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean)
      : [];
    if (out[cleanKey]) {
      out[cleanKey] = {
        pos: `${out[cleanKey].pos} / ${pos}`,
        def: `${out[cleanKey].def} · Also (${pos}): ${def}`,
        syns: Array.from(new Set([...out[cleanKey].syns, ...syns])),
      };
    } else {
      out[cleanKey] = { pos, def, syns };
    }
  }
  return out;
})();

